    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int q = Integer.parseInt(br.readLine().trim());
        String[] types = new String[q];
        int[] a = new int[q], b = new int[q];
        for (int i = 0; i < q; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            types[i] = st.nextToken();
            a[i] = Integer.parseInt(st.nextToken());
            if (!types[i].equals("TOP")) b[i] = Integer.parseInt(st.nextToken());
        }
        List<int[]> res = solve(types, a, b);
        StringBuilder sb = new StringBuilder();
        for (int[] r : res) {
            if (r.length == 0) {
                sb.append("-1\n");
            } else {
                for (int i = 0; i < r.length; i++) sb.append(r[i]).append(i + 1 < r.length ? " " : "\n");
